template <typename T>
struct Vector2D { T x, y; };

// Function Template for scaling operator*
template <typename T, typename Scalar>
Vector2D<T> operator*(const Vector2D<T>& vec, Scalar s) {
    return { vec.x * s, vec.y * s };
}

Vector2D<float> v = { 10.f, 20.f };

// T=float, Scalar=int
auto v_scaled_i = v * 2;

// T=float, Scalar=double
auto v_scaled_d = v * 0.5;
